import json

async def execute(self, inputs):
    from src.runtime.workflows import (
        get_workflow_registry, get_workflow_review, get_workflow_statistics,
        get_workflow_blueprint,
    )

    pack_name   = str(inputs.get('pack_name') or self.parameters.get('pack_name', 'industrial_hangar_pack') or '')
    exec_json   = str(inputs.get('execution_result_json') or '')

    try:
        registry = get_workflow_registry()
        pack     = registry.get_pack(pack_name)
        if not pack:
            self.log_error(f'[WorkflowReview] Pack not found: {pack_name!r}')
            return {
                'review_json': json.dumps({'ok': False, 'error': f'Pack not found: {pack_name}'}),
                'grade': 'F', 'overall_score': 0.0, 'production_ready': False,
                'findings_json': '[]', 'review_summary': f'Pack not found: {pack_name}',
                'ok': False, 'exec_out': True,
            }

        exec_result = {}
        if exec_json.strip():
            try:
                exec_result = json.loads(exec_json)
            except Exception:
                exec_result = {}

        builder   = get_workflow_blueprint()
        blueprint = builder.build_blueprint(pack)
        reviewer  = get_workflow_review()
        report    = reviewer.generate_report(pack, blueprint, exec_result)

        stats = get_workflow_statistics()
        stats.record_execution(
            pack_name,
            'committed' if report.production_ready else 'failed',
            score=report.overall_score,
            grade=report.grade,
        )

        self.log_info(
            f'[WorkflowReview] {pack_name!r}: '
            f'grade={report.grade}, score={report.overall_score:.2f}, '
            f'ready={report.production_ready}'
        )
        if report.findings:
            for f in report.findings:
                self.log_warning(f'[WorkflowReview] {f}')

        return {
            'review_json':     json.dumps(report.to_dict(), sort_keys=True),
            'grade':           report.grade,
            'overall_score':   report.overall_score,
            'production_ready': report.production_ready,
            'findings_json':   json.dumps(report.findings),
            'review_summary':  report.review_summary,
            'ok':              True,
            'exec_out':        True,
        }
    except Exception as e:
        self.log_error(f'[WorkflowReview] {e}')
        return {
            'review_json': json.dumps({'ok': False, 'error': str(e)}),
            'grade': 'F', 'overall_score': 0.0, 'production_ready': False,
            'findings_json': '[]', 'review_summary': str(e),
            'ok': False, 'exec_out': True,
        }

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Workflow_Review(BaseNode):
        name = 'hou_mcp_workflow_review'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Workflow_Review
